import {STORAGE_KEY,readState,initialState,isCorrect,dayKey,dayNumber,currentStreak,recordSolve,addReview,earnedBadges,BADGES} from './game-core.mjs';
const $=s=>document.querySelector(s),icon=window.icon,e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search),preview=params.get('preview')==='1',bank=window.CLINICAL_CASES;
const branded=document.body.classList.contains('consilium');
let storeAvailable=true;try{localStorage.setItem('case-club.check','1');localStorage.removeItem('case-club.check');}catch{storeAvailable=false;}
const storageKey=STORAGE_KEY+(params.get('qa')==='1'?'.qa':'');
let state=readState(storeAvailable?localStorage.getItem(storageKey):null),theme=branded?window.CASE_THEMES.find(t=>t.id==='bento'):(window.CASE_THEMES.find(t=>t.id===params.get('theme'))||window.CASE_THEMES[0]);
const today=dayKey(),dailyIndex=((dayNumber(today)-dayNumber('2026-10-28'))%bank.length+bank.length)%bank.length;
let current=bank.find(c=>c.id===params.get('case'))||bank[dailyIndex],session={opened:1,misses:[],finished:false,revealed:false,day:today};
if(preview){document.body.classList.add('preview');state=initialState();state.xp=456;state.days=Array.from({length:7},(_,i)=>new Date((dayNumber(today)-i)*86400000).toISOString().slice(0,10));bank.slice(10,16).forEach(c=>state.solved[c.id]={date:today,clues:3,misses:0,score:76,difficulty:c.difficulty,specialty:c.specialty});current=bank[0];session.opened=2;}
function save(){if(!preview&&storeAvailable)try{state.sessions[current.id]=session;localStorage.setItem(storageKey,JSON.stringify(state));}catch{storeAvailable=false;$('#preview-note').textContent='Сохранение недоступно: прогресс останется только до закрытия страницы';}}
function loadSession(){const saved=state.sessions[current.id];session=saved?.day===today?{...saved}:{opened:1,misses:[],finished:false,revealed:false,day:today};if(preview)session.opened=2;}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));}
const titles={clinical:['Клиническое мышление.<br><em>Каждый день.</em>','Один случай, шесть подсказок.<br>Сопоставь факты и найди диагноз.'],night:['Собери факты.<br><em>Увидь картину.</em>','Тихая практика для сложных решений.<br>Сегодня — ещё один клинический случай.'],pulse:['К точному диагнозу.<br><em>Шаг за шагом.</em>','Небольшая практика. Новое открытие.<br>Продолжи свой клинический маршрут.'],journal:['Наблюдать.<br><em>Сопоставлять.</em>','Клинический случай дня.<br>Шесть деталей, из которых складывается диагноз.'],atlas:['Твой клинический<br><em>атлас.</em>','Исследуй новые связи.<br>Каждый кейс расширяет картину.'],bento:['Практика<br><em>в деталях.</em>','Один клинический случай.<br>Несколько минут для себя.'],resident:['За каждым симптомом —<br><em>история.</em>','Открой клиническое дело.<br>Сопоставь детали и найди объяснение.'],differential:['Думай.<br><em>Различай.</em>','Клиническое мышление в действии.<br>Один случай. Шесть подсказок.'],synapse:['Соединяй факты.<br><em>Находи смысл.</em>','Новая связь каждый день.<br>Твоя практика клинического мышления.'],garden:['Маленькая практика.<br><em>Большой путь.</em>','Несколько минут внимания каждый день.<br>Расти в своём темпе.']};
function applyTheme(){document.body.dataset.theme=theme.id;$('#intro-title').innerHTML=branded?'Собери факты.<br><em>Найди диагноз.</em>':titles[theme.id][0];$('#intro-copy').innerHTML=branded?'Один клинический случай.<br>Новая возможность разобраться.':titles[theme.id][1];$('#theme-select').value=theme.id;const art=$('.artcore');art.dataset.icon=theme.id==='garden'?'leaf':theme.id==='pulse'?'heart':theme.id==='journal'?'award':'compass';icons();}
$('#theme-select').innerHTML=window.CASE_THEMES.map(t=>`<option value="${e(t.id)}">${e(t.name)}</option>`).join('');
$('#theme-select').addEventListener('change',ev=>{theme=window.CASE_THEMES.find(t=>t.id===ev.target.value);params.set('theme',theme.id);history.replaceState({},'',location.pathname+'?'+params);applyTheme();});
function renderProgress(){const solved=Object.keys(state.solved).length,level=Math.floor(state.xp/500)+1,xp=state.xp%500,streak=currentStreak(state.days,today),dayWord=streak%10===1&&streak%100!==11?'день':streak%10>=2&&streak%10<=4&&(streak%100<12||streak%100>14)?'дня':'дней';$('#streak-top').innerHTML=icon('flame',18)+streak+' '+dayWord;$('#xp-value').textContent=state.xp.toLocaleString('ru-RU');$('#level-value').textContent='Уровень '+level;$('#xp-track-fill').style.width=(xp/500*100)+'%';$('#xp-next').textContent=`Ещё ${500-xp} XP до следующего уровня`;$('#streak-value').textContent=streak;$('#streak-value').nextElementSibling.textContent=dayWord+' подряд';$('#solved-value').innerHTML=solved+'<span>/50</span>';$('#daily-goal').textContent=state.days.includes(today)?'Выполнена ✓':'1 кейс';
 const names=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],dow=(new Date().getDay()+6)%7,mon=dayNumber(today)-dow;$('#week').innerHTML=names.map((n,i)=>{const key=new Date((mon+i)*86400000).toISOString().slice(0,10),active=state.days.includes(key);return `<div class="week-day"><span>${n}</span><i class="${active?'active ':''}${key===today?'today':''}">${active?icon('check',11):''}</i></div>`;}).join('');
 const got=earnedBadges(state),next=BADGES.find(b=>!got.includes(b.id))||BADGES.at(-1);$('#next-badge-name').textContent=next.name;$('#next-badge-desc').textContent=next.desc;$('.nextbadge .medal').innerHTML=icon(next.icon,29);
 const milestones=$('#milestone-grid');
 if(milestones){milestones.innerHTML=['first','week','wide'].map(id=>{const b=BADGES.find(b=>b.id===id),earned=got.includes(id);return `<button class="milestone-item${earned?' earned':''}" type="button" aria-label="${e(b.name)}: ${e(b.desc)}"><span class="milestone-icon">${icon(b.icon,19)}</span><span><strong>${e(b.name)}</strong><small>${earned?'Получено':'Впереди'}</small></span></button>`;}).join('');milestones.querySelectorAll('button').forEach(b=>b.onclick=badges);}
}
function renderCase(){
 document.title=`${current.id} — ${branded?'Твой консилиум':'Кейс'}`;
 $('#case-id').textContent=(branded?'СЛУЧАЙ ':'ДЕЛО ')+current.id;
 $('#case-mode').textContent=current.id===bank[dailyIndex].id?'Кейс дня':'Свободная практика';
 $('#case-difficulty').textContent='Сложность '+current.difficulty+'/5';
 $('#clue-count').textContent=session.opened+' / 6 подсказок';
 const progress=$('#clue-progress');if(progress)progress.innerHTML=Array.from({length:6},(_,i)=>`<span class="${i<session.opened?'open':''}${i===session.opened-1?' current':''}"></span>`).join('');
 $('#clues').innerHTML=current.clues.slice(0,session.opened).map((c,i)=>`<article class="clue"><span class="clue-num">${String(i+1).padStart(2,'0')}</span><p>${e(c)}</p></article>`).join('');
 const rest=6-session.opened;$('#remaining').innerHTML=rest?icon('lock',12)+`Ещё ${rest} ${rest===1?'подсказка':rest<5?'подсказки':'подсказок'} пока скрыты`:'Все подсказки открыты';
 $('#guesses').innerHTML=session.misses.map(s=>`<div class="guess">${e(s)} — ответ не принят</div>`).join('');
 $('#hint-button').disabled=session.opened>=6||session.finished||preview;$('#answer-form').hidden=session.finished;$('#reveal-button').hidden=session.finished;$('#hint-button').hidden=session.finished;$('#result').hidden=!session.finished;
 if(session.finished)showResult(!session.revealed,0,false);
}
function choose(c){current=c;loadSession();$('#diagnosis').value='';params.set('case',c.id);history.replaceState({},'',location.pathname+'?'+params);renderCase();$('#modal').close();window.scrollTo({top:0,behavior:'smooth'});}
function showResult(won,reward,first){const sources=[current.source1,current.source2].filter(Boolean);$('#result').hidden=false;$('#result').innerHTML=`<div class="result-tag">${won?'Диагноз найден':'Разбор случая'}</div><h3>${e(current.diagnosis)}</h3>${won&&first?`<p class="result-reward">+${reward} XP · ${session.opened} из 6 подсказок</p>`:''}${won&&!first?'<p>Кейс уже был решён. За повторное решение XP не начисляются.</p>':''}<p>${e(current.explanation)}</p><details><summary>Близкие диагнозы и клинические нюансы</summary><p>${e(current.differential)}</p><p>${e(current.nuance)}</p></details><div class="source-links">${sources.map((u,i)=>`<a href="${e(u)}" target="_blank" rel="noopener noreferrer">${i?'Дополнительный источник':'Клинический источник'} ↗</a>`).join('')}</div><button id="next-case" class="primary" type="button">Ещё один случай ${icon('arrow',17)}</button>`;$('#next-case').onclick=()=>choose(bank.find(c=>!state.solved[c.id]&&c.id!==current.id)||bank[(bank.indexOf(current)+1)%bank.length]);}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000);}
$('#answer-form').addEventListener('submit',ev=>{ev.preventDefault();if(preview||session.finished)return;const value=$('#diagnosis').value.trim();if(!value)return;if(isCorrect(current,value)){const before=earnedBadges(state);session.finished=true;session.revealed=false;const result=recordSolve(state,current,{clues:session.opened,misses:session.misses.length,today});save();renderCase();showResult(true,result.reward,result.first);renderProgress();const added=earnedBadges(state).filter(id=>!before.includes(id));if(added.length)toast('Новое достижение: '+BADGES.filter(b=>added.includes(b.id)).map(b=>b.name).join(', '));$('#result').scrollIntoView({behavior:'smooth',block:'nearest'});}else{session.misses.push(value);session.opened=Math.min(6,session.opened+1);$('#diagnosis').value='';save();renderCase();toast(session.opened<6?'Ответ не совпал. Открыта следующая подсказка.':'Ответ не совпал. Можно попробовать ещё раз или открыть разбор.');}});
$('#hint-button').onclick=()=>{if(session.opened<6&&!preview){session.opened++;save();renderCase();}};
let revealArmed=false;$('#reveal-button').onclick=()=>{if(preview)return;if(!revealArmed){revealArmed=true;$('#reveal-button').textContent='Да, открыть разбор';setTimeout(()=>{revealArmed=false;$('#reveal-button').textContent='Показать ответ';},5000);return;}revealArmed=false;session.finished=true;session.revealed=true;addReview(state,current.id,today);save();renderCase();showResult(false,0,false);toast('Кейс добавлен в повторение на завтра.');};
const modal=$('#modal');$('#modal-close').onclick=()=>modal.close();modal.onclick=ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)modal.close();}};
function badges(){const got=earnedBadges(state);$('#modal-eyebrow').textContent='ЛИЧНАЯ КОЛЛЕКЦИЯ';$('#modal-title').textContent=`Достижения ${got.length}/10`;$('#modal-content').innerHTML='<div class="badges-grid">'+BADGES.map(b=>`<article class="badge-card ${got.includes(b.id)?'earned':''}"><div class="medal">${icon(b.icon,29)}</div><h3>${e(b.name)}</h3><p>${e(b.desc)}</p><span class="badge-state">${got.includes(b.id)?'ПОЛУЧЕНО':'ВПЕРЕДИ'}</span></article>`).join('')+'</div>';modal.showModal();}
function archive(tab='all'){const due=Object.keys(state.review).filter(id=>state.review[id]<=today);$('#modal-eyebrow').textContent='ТВОЯ ПРАКТИКА';$('#modal-title').textContent=tab==='all'?'Клинические случаи':'Повторение';const list=tab==='all'?bank:bank.filter(c=>due.includes(c.id));$('#modal-content').innerHTML=`<div class="archive-tabs"><button id="archive-all" type="button" class="${tab==='all'?'active':''}">Все 50 кейсов</button><button id="archive-review" type="button" class="${tab==='review'?'active':''}">Повторение · ${due.length}</button></div><div class="case-list">${list.map(c=>`<button type="button" data-case="${e(c.id)}"><span>${e(c.id)}</span><small>Сложность ${c.difficulty}/5</small><span class="list-status">${state.solved[c.id]?'Решён ✓':'Открыть '+icon('arrow',14)}</span></button>`).join('')||'<p class="empty-state">На сегодня повторений нет. Кейсы, для которых открыт разбор, появятся здесь на следующий день.</p>'}</div>`;$('#archive-all').onclick=()=>archive('all');$('#archive-review').onclick=()=>archive('review');$('#modal-content').querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>choose(bank.find(c=>c.id===b.dataset.case)));if(!modal.open)modal.showModal();}
$('#achievements-button').onclick=badges;$('#all-badges').onclick=badges;$('#rail-badges').onclick=badges;$('#archive-button').onclick=()=>archive();$('#rail-archive').onclick=()=>archive();$('#daily-button').onclick=()=>choose(bank[dailyIndex]);
if($('#milestone-all'))$('#milestone-all').onclick=badges;
if(preview){$('#preview-note').textContent='Демо-профиль: пример серии, XP и достижений';$('#answer-form').querySelectorAll('input,button').forEach(el=>el.disabled=true);}else{loadSession();if(!storeAvailable)$('#preview-note').textContent='Сохранение недоступно: прогресс действует до закрытия страницы';}
applyTheme();renderCase();renderProgress();
